function writeData(writer, data) {
  let i = data.length;
  function write() {
    let ok = true;
    do {
      i--;
      if (i === 0) writer.write(data[i]);
      else ok = writer.write(data[i]);
    } while (i > 0 && ok);
    if (i > 0) writer.once('drain', write);
  }
  write();
}

